// src/proxy/socketActivation.ts
var SD_LISTEN_FDS_START = 3;
function socketActivationFd(env = process.env, pid = process.pid) {
  if (!/^\d+$/.test(env.LISTEN_PID ?? "") || !/^\d+$/.test(env.LISTEN_FDS ?? ""))
    return;
  const listenPid = Number(env.LISTEN_PID);
  const fds = Number(env.LISTEN_FDS);
  if (!Number.isSafeInteger(listenPid) || listenPid !== pid)
    return;
  if (!Number.isSafeInteger(fds) || fds < 1)
    return;
  return SD_LISTEN_FDS_START;
}
function isModelRequestPath(path) {
  return /^\/v1\/(?:messages|chat\/completions|responses)(?:[/?]|$)/.test(path);
}
function parseIdleExitSeconds(env = process.env) {
  const raw = env.MERIDIAN_IDLE_EXIT_SECONDS ?? env.CLAUDE_PROXY_IDLE_EXIT_SECONDS;
  if (raw === undefined || raw === "")
    return;
  if (!/^\d+$/.test(raw))
    return;
  const seconds = Number(raw);
  if (!Number.isSafeInteger(seconds) || seconds < 1 || seconds > Number.MAX_SAFE_INTEGER / 1000)
    return;
  return seconds;
}

export { SD_LISTEN_FDS_START, socketActivationFd, isModelRequestPath, parseIdleExitSeconds };
